import{mkdir,writeFile}from'node:fs/promises';import{resolve,join}from'node:path';import{chromium,firefox}from'playwright';
const out=resolve('diagnostics/changed-services-responsive-20261105');await mkdir(out,{recursive:true});const cases=[{slug:'إلغاء-ملف-أو-بطاقة-المنشأة',host:'www.atlp.ae'},{slug:'legacy-service-67abe5ccf3',host:'www.investindubai.gov.ae'},{slug:'تقرير-تقييم-المنشأة',host:'mohre.gov.ae'}],report={sourceSha:process.env.HB_SOURCE_SHA,scope:'ONLY_ADDITIONAL_VIEWPORTS_FOR_THREE_CHANGED_RECORDS; accepted_1440_390_320_not_repeated',cases:[],errors:[]};
for(const[engine,type]of[['chrome',chromium],['firefox',firefox]]){const browser=await type.launch({headless:true,...(engine==='chrome'?{executablePath:process.env.HB_BROWSER_PATH}:{})});try{for(const service of cases)for(const locale of['ar','en'])for(const width of[1366,768,430,360]){const page=await browser.newPage({viewport:{width,height:width>=768?960:844},deviceScaleFactor:1}),row={engine,slug:service.slug,locale,width,route:(locale==='en'?'/en':'')+'/services/'+service.slug+'/'},errors=[];page.on('pageerror',e=>errors.push(e.message));try{const response=await page.goto('https://hossambahr.com'+row.route,{waitUntil:'networkidle'});await page.evaluate(()=>document.fonts.ready);row.title=await page.locator('h1').innerText();row.layout=await page.evaluate(()=>{const h=document.querySelector('h1'),r=h.getBoundingClientRect();return{scrollWidth:document.documentElement.scrollWidth,viewport:innerWidth,heading:{left:r.left,right:r.right,width:r.width}};});if(response.status()!==200||!row.title||row.layout.scrollWidth>width||row.layout.heading.left<0||row.layout.heading.right>width)throw Error('Response or headline/page geometry failed');
const links=page.locator('#service-execution-options a');if(await links.count()<2)throw Error('Missing adjacent execution pathways');row.paths=[];for(let i=0;i<2;i++){const a=links.nth(i);await a.scrollIntoViewIfNeeded();const state=await a.evaluate(a=>{const r=a.getBoundingClientRect(),top=document.elementFromPoint(r.x+r.width/2,r.y+r.height/2);return{href:a.href,width:r.width,height:r.height,uncovered:!!top&&(top===a||a.contains(top))};});if(state.width<44||state.height<44||!state.uncovered)throw Error('Execution action clipped, covered or too small');row.paths.push(state);}
const government=new URL(row.paths[0].href),assisted=new URL(row.paths[1].href),message=assisted.searchParams.get('text')||'';if(government.hostname!==service.host||assisted.origin!=='https://wa.me'||assisted.pathname!=='/971503780460'||!message.includes(row.title)||!message.includes('https://hossambahr.com'+row.route))throw Error('Government or assisted context mismatch');if(service.slug==='تقرير-تقييم-المنشأة'&&await page.locator('[data-guidance-fact-limits]').count()!==1)throw Error('Compact guidance missing');if(service.slug==='إلغاء-ملف-أو-بطاقة-المنشأة'&&!government.pathname.startsWith('/'+locale+'/'))throw Error('Official card language lost');
if(errors.length)throw Error(errors.join(';'));if(engine==='chrome'&&service.slug==='تقرير-تقييم-المنشأة'){await page.evaluate(()=>window.scrollY);row.screenshot=locale+'-'+width+'.jpg';await page.screenshot({path:join(out,row.screenshot),type:'jpeg',quality:85,fullPage:true});}row.status='PASS';row.noSubmissionOrMessageSent=true;}catch(e){row.status='FAIL';row.error=e.message;row.pageErrors=errors;report.errors.push(row);}finally{report.cases.push(row);await page.close();}}}finally{await browser.close();}}
report.status=report.errors.length?'FAIL':'LIVE_ADDITIONAL_RESPONSIVE_PASS';await writeFile(join(out,'report.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({status:report.status,cases:report.cases.length,errors:report.errors}));if(report.errors.length)process.exitCode=1;